import{_ as e,o as t,c as r,ah as l}from"./chunks/framework.BdHuibk5.js";const o="/assets/%E5%89%8D%E7%AB%AF%E5%9F%B9%E8%AE%AD%E6%A1%86%E6%9E%B63.0.BuDtBXdX.png",b=JSON.parse('{"title":"前端知识体系","description":"","frontmatter":{},"headers":[],"relativePath":"front-end/index.md","filePath":"front-end/index.md","lastUpdated":1789440063000}'),i={name:"front-end/index.md"};function n(h,a,d,s,p,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="前端知识体系" tabindex="-1">前端知识体系 <a class="header-anchor" href="#前端知识体系" aria-label="Permalink to &quot;前端知识体系&quot;">​</a></h1><p>用一张持续生长的知识地图，串起前端学习与能力进阶的全貌。</p><p>这里不是零散内容的堆叠，而是一套从基础到进阶的前端认知框架。你可以把它当作学习路径、知识索引，也可以把它当作定位短板与规划下一步的参考坐标。</p><h2 id="知识鱼骨图" tabindex="-1">知识鱼骨图 <a class="header-anchor" href="#知识鱼骨图" aria-label="Permalink to &quot;知识鱼骨图&quot;">​</a></h2><p>一张全面、持续更新的前端在线版技术鱼骨大图</p><p><img src="'+o+'" alt="前端培训框架3.0" loading="lazy"></p><h2 id="推荐阅读方式" tabindex="-1">推荐阅读方式 <a class="header-anchor" href="#推荐阅读方式" aria-label="Permalink to &quot;推荐阅读方式&quot;">​</a></h2><ul><li>想建立全局认知：先看整体鱼骨图，再进入对应阶段展开阅读</li><li>想规划学习路线：按“入门 -&gt; 初阶 -&gt; 中阶 -&gt; 高阶”逐步推进</li><li>想查缺补漏：把当前工作遇到的问题映射到对应能力模块中</li></ul><h2 id="四个成长阶段" tabindex="-1">四个成长阶段 <a class="header-anchor" href="#四个成长阶段" aria-label="Permalink to &quot;四个成长阶段&quot;">​</a></h2><h3 id="入门" tabindex="-1">入门 <a class="header-anchor" href="#入门" aria-label="Permalink to &quot;入门&quot;">​</a></h3><p>聚焦前端基础能力，包括 HTML、CSS、JavaScript 与浏览器等核心知识，是后续工程化与框架能力的底座。</p><h3 id="初阶" tabindex="-1">初阶 <a class="header-anchor" href="#初阶" aria-label="Permalink to &quot;初阶&quot;">​</a></h3><p>开始进入真实项目开发需要的工具链与框架能力，包括开发工具、包管理、常见框架以及 CSS / JS / 动画库。</p><h3 id="中阶" tabindex="-1">中阶 <a class="header-anchor" href="#中阶" aria-label="Permalink to &quot;中阶&quot;">​</a></h3><p>面向工程质量与复杂度处理，关注工程化基础、性能优化、综合能力、设计模式、TypeScript、跨平台开发与服务端渲染。</p><h3 id="高阶" tabindex="-1">高阶 <a class="header-anchor" href="#高阶" aria-label="Permalink to &quot;高阶&quot;">​</a></h3><p>更强调体系化建设与底层理解，包括工程体系、框架原理、微前端、Node.js 与能力扩展方向。</p><h2 id="为什么这样组织" tabindex="-1">为什么这样组织 <a class="header-anchor" href="#为什么这样组织" aria-label="Permalink to &quot;为什么这样组织&quot;">​</a></h2><p>前端知识并不是孤立存在的。把内容按阶段组织，可以更自然地建立整体认知，也更方便在实践中看见自己的位置、短板与成长方向。</p><h2 id="知识鱼骨图的整体架构思路" tabindex="-1">知识鱼骨图的整体架构思路 <a class="header-anchor" href="#知识鱼骨图的整体架构思路" aria-label="Permalink to &quot;知识鱼骨图的整体架构思路&quot;">​</a></h2><p>从 <strong>入门 -&gt; 初阶 -&gt; 中阶 -&gt; 高阶</strong> 的维度讲述前端成长路线，既强调知识广度，也强调能力进阶过程中的结构化理解。</p><h2 id="彩蛋-前端知识图谱" tabindex="-1">彩蛋：前端知识图谱 <a class="header-anchor" href="#彩蛋-前端知识图谱" aria-label="Permalink to &quot;彩蛋：前端知识图谱&quot;">​</a></h2><p>前端的发展很快，在很多方面都会有各种新的知识出现，因此对于前端的知识图谱和学习路线，并没有一个权威的标准，但有不少比较全面和有参考价值的提案。 我们应该做的是根据这些提案，建立自己的知识体系，并在成长过程中和前端发展过程中动态调整。</p><p>下面是几个影响比较大的知识图谱和学习路线。</p><ul><li><a href="https://mp.weixin.qq.com/s/c8WXCTl6wMqd2AJktX7SIg" target="_blank" rel="noreferrer">云栖大会上，阿里巴巴重磅发布前端知识图谱</a></li><li><a href="https://www.runoob.com/w3cnote/web-developer-learn-path.html" target="_blank" rel="noreferrer">Web 开发者学习路线图</a></li><li><a href="https://zhuanlan.zhihu.com/p/164701269" target="_blank" rel="noreferrer">前端学习路线</a></li></ul>',25)])])}const f=e(i,[["render",n]]);export{b as __pageData,f as default};
